// Hi-res textures for the 'high' / 'ultra' render quality: bun tools/hires/build.ts
//
// Reads the disc textures generated by tools/g3d/build_models.py (public/assets/models/textures,
// public/assets/effects) and writes public/assets/hires/ + manifest.json. Deterministic (seeded),
// ~1 min. The game falls back to the original textures for anything missing here.
//
//   --only <substr>   rebuild matching keys only (the manifest keeps the other entries)
//   --sheet <png>     also write a before/after contact sheet of what was built
//
// Recipes (ops.ts): wood = Lanczos + unsharp + fibres along the source's grain direction;
// cork = Lanczos + cellular granules; crisp = edge-aware upscale for flat art; smooth =
// Mitchell for soft gradients (shadows, glows, env maps).

import { createHash } from 'node:crypto'
import { existsSync, readFileSync, readdirSync, writeFileSync, mkdirSync } from 'node:fs'
import { crispUpscale, cork, smoothUpscale, wood, type Wrap, resize } from './ops'
import { decodePng, img, writePng, type Img } from './png'

const SRC = 'public/assets/'
const OUT = 'public/assets/hires/'

type Recipe =
  | { kind: 'wood'; scale: number; amp?: number; sharpen?: number; wrap?: Wrap; sigma?: number }
  | { kind: 'cork'; scale: number }
  | { kind: 'crisp'; scale: number; wrap?: Wrap; strength?: number }
  | { kind: 'smooth'; scale: number; wrap?: Wrap }
  | { kind: 'hole'; scale: number }

/** key (as the runtime asks for it) -> source file + recipe */
const jobs: { key: string; src: string; r: Recipe }[] = []
const add = (key: string, src: string, r: Recipe) => existsSync(SRC + src) && jobs.push({ key, src, r })

const T = 'models/textures/'
for (const f of ['tnk_field_16_9', 'tnk_field_4_3']) {
  for (const n of ['floor_face', 'floor_lower']) add(`${f}/${n}`, `${T}${f}/${n}.png`, { kind: 'wood', scale: 2, amp: 0.03, sharpen: 0.3 })
  for (const n of ['block_other_a', 'block_other_b', 'block_other_b_test', 'block_other_c'])
    add(`${f}/${n}`, `${T}${f}/${n}.png`, { kind: 'wood', scale: 8, amp: 0.05 })
  for (const n of ['block_shadow_a', 'block_shadow_b', 'block_shadow_c', 'block_shadow_d', 'block_shadow_h'])
    add(`${f}/${n}`, `${T}${f}/${n}.png`, { kind: 'smooth', scale: 4 })
  add(`${f}/tnk_tank_env`, `${T}${f}/tnk_tank_env.png`, { kind: 'smooth', scale: 4 })
}
// the floor model's lerp uses the tnk_block copies (models.ts floorMaterial)
for (const n of ['floor_face', 'floor_lower']) add(`tnk_block/${n}`, `${T}tnk_block/${n}.png`, { kind: 'wood', scale: 2, amp: 0.03, sharpen: 0.3 })
add('tnk_block/block.1', `${T}tnk_block/block.1.png`, { kind: 'wood', scale: 8, amp: 0.05 })
add('tnk_block/block.2', `${T}tnk_block/block.2.png`, { kind: 'cork', scale: 8 })
add('tnk_block/block_harf.1', `${T}tnk_block/block_harf.1.png`, { kind: 'hole', scale: 4 })
add('tnk_block/tnk_tank_env', `${T}tnk_block/tnk_tank_env.png`, { kind: 'smooth', scale: 4 })
add('tnk_block_shadow/block_shadow', `${T}tnk_block_shadow/block_shadow.png`, { kind: 'smooth', scale: 4, wrap: 'repeat' })
for (const n of ['blue', 'red']) add(`tnk_tank/tank_${n}`, `${T}tnk_tank/tank_${n}.png`, { kind: 'crisp', scale: 16, wrap: 'repeat' })
for (const n of ['brown', 'ash', 'marin', 'pink', 'yellow', 'violet', 'green', 'white', 'black'])
  add(`tnk_tank/tank_${n}`, `${T}tnk_tank/tank_${n}.png`, { kind: 'wood', scale: 16, amp: 0.03, sharpen: 0.2, sigma: 0.8, wrap: 'repeat' })
add('tnk_tank/tank_shadow', `${T}tnk_tank/tank_shadow.png`, { kind: 'smooth', scale: 8 })
add('tnk_tank/tnk_tank_env', `${T}tnk_tank/tnk_tank_env.png`, { kind: 'smooth', scale: 4 })
for (const n of ['blue', 'red', 'white']) add(`tnk_check/check_${n}`, `${T}tnk_check/check_${n}.png`, { kind: 'crisp', scale: 4 })
add('tnk_mine/mine_env', `${T}tnk_mine/mine_env.png`, { kind: 'smooth', scale: 4 })
add('tnk_mine/mine_shadow', `${T}tnk_mine/mine_shadow.png`, { kind: 'smooth', scale: 8 })
add('shell/shell', `${T}shell/shell.png`, { kind: 'crisp', scale: 8 })

// effect sprites: quarter images are drawn mirrored, so resample with mirrored borders
const SHARP_FX = new Set(['pc_box_hit06', 'pc_sht_cursor1', 'pc_sht_cursor2', 'pc_sht_hahen1', 'pc_tnk_rock03', 'pc_clr_kira01', 'pc_clr_stardust01'])
for (const f of readdirSync(SRC + 'effects/textures')) {
  const n = f.replace(/\.png$/, '')
  if (n.startsWith('#')) continue
  add(`fx/${n}`, `effects/textures/${f}`, SHARP_FX.has(n) ? { kind: 'crisp', scale: 4, wrap: 'mirror' } : { kind: 'smooth', scale: 4, wrap: 'mirror' })
}
for (const f of readdirSync(SRC + 'effects/tread_marks')) add(`tread/${f.replace(/^tnk_mark_|\.png$/g, '')}`, `effects/tread_marks/${f}`, { kind: 'crisp', scale: 4 })

function run(src: Img, r: Recipe, seed: number): Img {
  switch (r.kind) {
    case 'wood':
      return wood(src, r.scale, { wrap: r.wrap ?? 'repeat', amp: r.amp, sharpen: r.sharpen, sigma: r.sigma, seed })
    case 'cork':
      return cork(src, r.scale, { seed })
    case 'crisp':
      return crispUpscale(src, r.scale, { wrap: r.wrap ?? 'clamp', strength: r.strength })
    case 'smooth':
      return smoothUpscale(src, r.scale, r.wrap ?? 'clamp')
    case 'hole': {
      // wood inside the hole (colour) + a crisp circular edge (alpha-tested at 128)
      const col = wood(src, r.scale, { wrap: 'clamp', amp: 0.04, seed })
      const a = crispUpscale(src, r.scale, { strength: 3 })
      for (let i = 0; i < a.w * a.h; i++) col.d[i * 4 + 3] = a.d[i * 4 + 3]
      return col
    }
  }
}

const args = process.argv.slice(2)
const only = args.includes('--only') ? args[args.indexOf('--only') + 1] : null
const sheetPath = args.includes('--sheet') ? args[args.indexOf('--sheet') + 1] : null

const manifestPath = OUT + 'manifest.json'
const manifest: { version: number; textures: Record<string, { file: string; w: number; h: number }> } =
  only && existsSync(manifestPath) ? JSON.parse(readFileSync(manifestPath, 'utf8')) : { version: 1, textures: {} }
const byHash = new Map<string, { file: string; w: number; h: number }>()
const built: { before: Img; after: Img }[] = []
const t0 = performance.now()
for (const j of jobs) {
  if (only && !j.key.includes(only)) continue
  const buf = readFileSync(SRC + j.src)
  const hash = createHash('md5').update(buf).update(JSON.stringify(j.r)).digest('hex').slice(0, 10)
  let entry = byHash.get(hash)
  if (!entry) {
    const src = decodePng(buf)
    const seed = parseInt(hash.slice(0, 6), 16)
    const t = performance.now()
    const out = run(src, j.r, seed)
    const file = `${j.key}.png`
    writePng(OUT + file, out)
    entry = { file, w: out.w, h: out.h }
    byHash.set(hash, entry)
    console.log(`${j.key.padEnd(34)} ${src.w}x${src.h} -> ${out.w}x${out.h} ${j.r.kind} ${((performance.now() - t) / 1000).toFixed(1)}s`)
    if (sheetPath) built.push({ before: src, after: out })
  }
  manifest.textures[j.key] = entry
}
mkdirSync(OUT, { recursive: true })
writeFileSync(manifestPath, JSON.stringify(manifest, null, 1))
console.log(`${Object.keys(manifest.textures).length} textures, ${((performance.now() - t0) / 1000).toFixed(1)}s -> ${manifestPath}`)

if (sheetPath && built.length) {
  // before (nearest, as the GPU would magnify) | after, each 384 px tall
  const S = 384
  const rows = built.map(({ before, after }) => {
    const k = S / Math.max(after.w, after.h)
    const w = Math.round(after.w * k), h = Math.round(after.h * k)
    return { a: resize(before, w, h, { kernel: 'mitchell' }), b: resize(after, w, h, { kernel: 'lanczos' }), w, h }
  })
  const W = Math.max(...rows.map((r) => r.w * 2 + 24)) * 2
  const perRow = 2
  const H = Math.ceil(rows.length / perRow) * (S + 8)
  const sheet = img(W, H)
  rows.forEach((r, n) => {
    const ox = (n % perRow) * (W / perRow), oy = Math.floor(n / perRow) * (S + 8)
    for (const [im, dx] of [[r.a, 0], [r.b, r.w + 8]] as const)
      for (let y = 0; y < r.h; y++)
        for (let x = 0; x < r.w; x++) {
          const si = (y * r.w + x) * 4, di = ((oy + y) * W + ox + dx + x) * 4
          const a = im.d[si + 3], bg = ((x >> 4) + (y >> 4)) & 1 ? 0.5 : 0.7
          for (let c = 0; c < 3; c++) sheet.d[di + c] = im.d[si + c] * a + bg * (1 - a)
          sheet.d[di + 3] = 1
        }
  })
  writePng(sheetPath, sheet)
}
